/* Presentation only: locate existing notes in the already authorized original essay. */
(function(root){
'use strict';
function paragraphs(text){const result=[];for(const m of text.matchAll(/[^\r\n]+/g)){const trim=m[0].trim();if(trim)result.push({start:m.index+m[0].indexOf(trim),end:m.index+m[0].length,text:m[0]});}return result;}
function sentenceAt(text,offset){const segments=[...new Intl.Segmenter('en',{granularity:'sentence'}).segment(text)];let number=1;for(let i=0;i<segments.length;i++){if(segments[i].index<=offset)number=i+1;}return number;}
function location(text,start,end){const parts=paragraphs(text),a=parts.findIndex(p=>start>=p.start&&start<p.end),b=parts.findIndex(p=>Math.max(start,end-1)>=p.start&&Math.max(start,end-1)<p.end);if(a<0||b<0)return '';const standard=parts.length===4&&/^In conclusion\b/i.test(parts[3].text.trim()),name=i=>standard?['Mở bài','Body 1','Body 2','Kết bài'][i]:'Đoạn '+(i+1),first=sentenceAt(parts[a].text,start-(parts[a].start-parts[a].text.indexOf(parts[a].text.trim()))),last=sentenceAt(parts[b].text,end-1-(parts[b].start-parts[b].text.indexOf(parts[b].text.trim())));return a===b?name(a)+' · Câu '+first+(first===last?'':'–'+last):name(a)+' · Câu '+first+' → '+name(b)+' · Câu '+last;}
if(typeof module!=='undefined')module.exports={location};
if(!root.document)return;
const script=root.document.currentScript,className=script?.dataset.class,week=script?.dataset.week;if(!className||!/^W\d+$/.test(week||''))return;
const done=new WeakSet();let scheduled=false;
function draw(){scheduled=false;for(const dialog of root.document.querySelectorAll('dialog.wr-dialog[open]')){if(done.has(dialog))continue;const kicker=dialog.querySelector('.wr-head .wr-kicker')?.textContent||'',parts=kicker.split('·').map(x=>x.trim());if(parts[0]!==className||!parts.includes(week))continue;const essay=dialog.querySelector('#wr-original .wr-essay');if(!essay)continue;const text=essay.textContent,positions=new Map();for(const mark of essay.querySelectorAll('[data-wr-notes]')){const range=root.document.createRange();range.selectNodeContents(essay);range.setEndBefore(mark);const start=range.toString().length,end=start+mark.textContent.length;for(const id of mark.dataset.wrNotes.split(',')){const old=positions.get(id);positions.set(id,{start:old?Math.min(start,old.start):start,end:old?Math.max(end,old.end):end});}}done.add(dialog);
for(const note of dialog.querySelectorAll('.wr-note')){const id=note.id.match(/^wr-note-(\d+)$/)?.[1],pos=positions.get(id),heading=note.querySelector('h5');if(!pos||!heading)continue;const where=location(text,pos.start,pos.end);if(!where)continue;const old=heading.textContent,split=old.indexOf(' · ');let description=split<0?'':old.slice(split+3);if(/^Lỗi\s*\d+\s*·\s*(Mở bài|Body\s*\d+|Kết bài|Đoạn\s*\d+)\s*·\s*Câu\s*[\d–-]+$/i.test(description))description='';const label='Lỗi '+(Number(id)+1)+' · '+where;heading.textContent=label;note.dataset.mttLocation='true';if(description){const detail=root.document.createElement('small');detail.textContent=description;detail.style.cssText='display:block;margin-top:.4em;font-weight:normal;font-size:.85em';heading.append(detail);}for(const mark of essay.querySelectorAll('[data-wr-notes]'))if(mark.dataset.wrNotes.split(',').includes(id))mark.setAttribute('aria-label','Xem '+label);}
}}
function schedule(){if(scheduled)return;scheduled=true;root.requestAnimationFrame(draw);}
new root.MutationObserver(schedule).observe(root.document.body,{childList:true,subtree:true,attributes:true,attributeFilter:['open']});schedule();
})(typeof window!=='undefined'?window:globalThis);
